#[derive(Clone, Debug)]
pub struct RateLimiter {
    window_ms: u64,
    max_requests: u32,
    requests: Arc<Mutex<Vec<Instant>>>,
}

impl RateLimiter {
    pub fn new(window_ms: u64, max_requests: u32) -> Self {
        Self {
            window_ms,
            max_requests,
            requests: Arc::new(Mutex::new(Vec::new())),
        }
    }

    pub fn check_rate_limit(&self) -> bool {
        let mut reqs = self.requests.lock().unwrap();
        let now = Instant::now();
        let window = Duration::from_millis(self.window_ms);
        reqs.retain(|t| now.duration_since(*t) < window);
        if reqs.len() < self.max_requests as usize {
            reqs.push(now);
            true
        } else {
            false
        }
    }
}

#[derive(Clone, Debug)]
pub struct JobPayload {
    pub job_id: String,
    pub tenant_id: String,
    pub action: String,
    pub resource_filter: String,
    pub retry_count: u32,
}

pub struct QueryBuilder {
    base_table: String,
    conditions: Vec<String>,
    params: Vec<String>,
}

impl QueryBuilder {
    pub fn new(table: &str) -> Self {
        // Validate table name against allowlist
        let allowed_tables = ["resources", "notification_configs"];
        let safe_table = if allowed_tables.contains(&table) {
            table.to_string()
        } else {
            panic!("Invalid table name");
        };
        Self {
            base_table: safe_table,
            conditions: Vec::new(),
            params: Vec::new(),
        }
    }

    pub fn with_tenant(&mut self, tenant_id: &str) -> &mut Self {
        // Use parameterized query placeholder
        let idx = self.params.len() + 1;
        self.conditions.push(format!("tenant_id = ${}", idx));
        self.params.push(tenant_id.to_string());
        self
    }

    pub fn with_status(&mut self, status: &str) -> &mut Self {
        let idx = self.params.len() + 1;
        self.conditions.push(format!("status = ${}", idx));
        self.params.push(status.to_string());
        self
    }

    pub fn with_resource_filter(&mut self, filter: &str) -> &mut Self {
        // Resource filter uses our internal DSL: "field:value" pairs
        // Parse and validate the DSL before building SQL
        let (condition, new_params) = self.sanitize_filter_dsl(filter);
        self.conditions.push(condition);
        self.params.extend(new_params);
        self
    }

    fn sanitize_filter_dsl(&self, filter: &str) -> (String, Vec<String>) {
        // DSL format: "field_name:value" or "field_name:value1,value2"
        // We validate field names against allowlist
        let allowed_fields = ["name", "category", "priority", "region"];

        let parts: Vec<&str> = filter.splitn(2, ':').collect();
        if parts.len() != 2 {
            return ("1=1".to_string(), vec![]);
        }

        let field = parts[0].trim();
        let value = parts[1].trim();

        if !allowed_fields.contains(&field) {
            return ("1=1".to_string(), vec![]);
        }

        // Validate field name is alphanumeric
        if !field.chars().all(|c| c.is_alphanumeric() || c == '_') {
            return ("1=1".to_string(), vec![]);
        }

        // Handle comma-separated values for IN clause using parameters
        if value.contains(',') {
            let values: Vec<&str> = value.split(',').collect();
            let mut placeholders = Vec::new();
            let mut new_params = Vec::new();
            let base_idx = self.params.len() + 1;
            for (i, v) in values.iter().enumerate() {
                placeholders.push(format!("${}", base_idx + i));
                new_params.push(v.trim().to_string());
            }
            (format!("{} IN ({})", field, placeholders.join(", ")), new_params)
        } else {
            let idx = self.params.len() + 1;
            (format!("{} = ${}", field, idx), vec![value.to_string()])
        }
    }

    pub fn build(&self) -> (String, Vec<String>) {
        let where_clause = if self.conditions.is_empty() {
            String::new()
        } else {
            format!(" WHERE {}", self.conditions.join(" AND "))
        };
        (format!("SELECT * FROM {}{}", self.base_table, where_clause), self.params.clone())
    }
}

pub struct BackgroundWorker {
    db: DbConnection,
    rate_limiter: RateLimiter,
    max_retries: u32,
}

impl BackgroundWorker {
    pub fn new() -> Self {
        Self {
            db: DbConnection,
            rate_limiter: RateLimiter::new(60000, 100),
            max_retries: 3,
        }
    }

    pub fn process_job(&self, payload: &JobPayload) -> Result<(), String> {
        if !self.rate_limiter.check_rate_limit() {
            if payload.retry_count < self.max_retries {
                return Err("Rate limited, will retry".to_string());
            }
            return Err("Rate limit exceeded, max retries reached".to_string());
        }

        // Validate job_id is a valid UUID format
        if !Self::is_valid_uuid(&payload.job_id) {
            return Err("Invalid job_id format".to_string());
        }

        // Validate tenant_id format
        if !payload.tenant_id.chars().all(|c| c.is_alphanumeric() || c == '-') {
            return Err("Invalid tenant_id format".to_string());
        }

        match payload.action.as_str() {
            "cleanup" => self.handle_cleanup(payload),
            "archive" => self.handle_archive(payload),
            "notify" => self.handle_notify(payload),
            _ => Err(format!("Unknown action: {}", payload.action)),
        }
    }

    fn is_valid_uuid(s: &str) -> bool {
        let parts: Vec<&str> = s.split('-').collect();
        if parts.len() != 5 {
            return false;
        }
        let expected_lens = [8, 4, 4, 4, 12];
        parts.iter().zip(expected_lens.iter()).all(|(part, &len)| {
            part.len() == len && part.chars().all(|c| c.is_ascii_hexdigit())
        })
    }

    fn handle_cleanup(&self, payload: &JobPayload) -> Result<(), String> {
        let mut qb = QueryBuilder::new("resources");
        qb.with_tenant(&payload.tenant_id)
          .with_status("expired")
          .with_resource_filter(&payload.resource_filter);

        let (query, params) = qb.build();
        let param_refs: Vec<&str> = params.iter().map(|s| s.as_str()).collect();
        self.db.execute_parameterized(&query, &param_refs)?;
        Ok(())
    }

    fn handle_archive(&self, payload: &JobPayload) -> Result<(), String> {
        let mut qb = QueryBuilder::new("resources");
        qb.with_tenant(&payload.tenant_id)
          .with_status("completed")
          .with_resource_filter(&payload.resource_filter);

        let (query, params) = qb.build();
        let param_refs: Vec<&str> = params.iter().map(|s| s.as_str()).collect();
        self.db.execute_parameterized(&query, &param_refs)?;
        Ok(())
    }

    fn handle_notify(&self, payload: &JobPayload) -> Result<(), String> {
        // Use parameterized query for notification config lookup
        let query = "SELECT config FROM notification_configs WHERE job_ref = $1 AND tenant_id = $2";
        self.db.execute_parameterized(query, &[&payload.job_id, &payload.tenant_id])?;
        Ok(())
    }
}

